from pathlib import Path

def insert_before_sources(path, block):
    p=Path(path)
    text=p.read_text(encoding='utf-8')
    marker='\n## 五、公开来源'
    if marker not in text:
        marker='\n## 七、公开来源' if '\n## 七、公开来源' in text else '\n## 公开来源'
    if marker in text and block.strip() not in text:
        text=text.replace(marker, '\n'+block.strip()+'\n'+marker, 1)
    p.write_text(text.rstrip()+"\n", encoding='utf-8')

blocks={
'01-即时零售平台/补充资料/平台竞争指标表_流量供给履约医保处方药师.md': '''## 四、业务应用分析\n\n### 1. 流量入口：从“看得见”到“能成交”\n\n平台入口不能只看App月活或频道位置。买药入口真正有价值，需要能承接症状词、品牌词、急用药词和医保购药词，并把用户从搜索、推荐、活动页导向附近有库存的药店。若入口只带来曝光，但不能连接可售库存、医保支付或药师咨询，就只能说明平台有流量，不能说明买药业务有效。\n\n### 2. 供给能力：从“合作药店数”到“有效库存”\n\n合作药店数是弱指标，有效供给要看SKU、库存同步、夜间门店、DTP/OTC结构和区域密度。对急用药而言，附近3公里内是否有货比全国合作药店数更重要；对慢病和处方药而言，药店是否具备处方承接、医保结算和药师服务，比单纯上架更重要。\n\n### 3. 履约能力：从“送得快”到“送得稳”\n\n药品履约不能只看平均配送时效。缺货率、取消率、替代药解释、包装、温控、夜间履约、售后和投诉处理都会影响真实体验。平台若只用普通即时配送指标评价买药，容易高估自身能力。\n\n### 4. 医保、处方和药师：决定买药能否从OTC走向慢病复购\n\nOTC急用药可以先由流量、库存和履约驱动，但处方药、慢病药和DTP药需要医保支付、处方来源、药师审方和患者服务。平台竞争的长期分化点不在“谁能送药”，而在谁能把医保、处方和药师服务嵌入交易链路。\n''',
'01-即时零售平台/补充资料/平台医药合规边界_处方医保履约.md': '''## 四、业务应用分析\n\n### 1. 平台合规不是一个部门问题，而是交易链路问题\n\n处方、医保和履约分别发生在不同环节：处方在问诊和购药前，医保在支付结算时，履约在药店出库和配送后。平台如果只在页面上提示“需处方”或“支持医保”，但没有把处方来源、审方记录、医保结算和配送记录连起来，合规链路仍然是不完整的。\n\n### 2. 医保支付会提高平台和药店的准入门槛\n\n医保支付不是普通支付方式。它要求实名、定点资格、支付范围、结算记录和基金风控。平台要做线上医保买药，必须能证明哪家药店、哪个药品、哪个用户、哪笔支付和哪个配送记录对应起来。\n\n### 3. 履约合规决定药品服务能不能规模化\n\n药品履约涉及质量、包装、追溯和售后。平台买药规模越大，异常订单、缺货、替代药、退换货和投诉处理越重要。普通配送网络可以降低时效成本，但不能替代药品质量管理。\n''',
'07-政策与监管库/医保政策/医保政策汇总.md': '''## 四、政策逻辑与业务应用分析\n\n### 1. 医保政策不是单一支付政策，而是“支付 + 定点 + 监管”的组合\n\n医保支付能降低用户现金支出，但它同时要求定点资格、协议管理、基金监管和费用结算。平台如果只看到“医保可支付”的用户吸引力，而忽略定点药店、支付范围和基金风控，就会把医保理解成普通支付工具。\n\n### 2. 定点零售药店是线上医保买药的关键承接点\n\n线上医保购药不是平台单独完成的，药店是否定点、是否具备医保结算、处方承接和数据上传能力，决定平台入口能否转化为真实交易。对平台来说，筛选药店时不能只看距离和库存，还要看医保服务能力。\n\n### 3. 门诊统筹和慢特病会改变平台买药的需求结构\n\n普通OTC更多是急用药需求，门诊统筹和慢特病更接近长期复购和处方续配。若地方政策允许定点零售药店承接相关支付，平台买药的价值就会从“临时送药”延伸到慢病管理和复购服务。\n\n### 4. 医保目录决定“能不能支付”，不决定“能不能买到”\n\n药品进入医保目录只说明支付资格，实际能否在线购买，还要看地方执行、定点药店库存、处方要求和平台接入。药企不能把目录准入直接理解为O2O销量机会，仍要看院外渠道和药店承接能力。\n''',
'07-政策与监管库/处方药监管/处方药监管政策汇总.md': '''## 四、政策逻辑与业务应用分析\n\n### 1. 处方药线上销售的核心不是“能不能展示”，而是“处方从哪里来”\n\n处方药在线交易必须回答处方来源、患者身份、复诊条件和审方责任。平台页面展示处方药，只能说明存在信息入口，不能说明交易链路已经合规。真正影响业务的是处方能否被合法开具、传输、审核和留存。\n\n### 2. 审方是药店和药师价值的核心\n\n处方药不应被当作普通SKU处理。药店能否承接处方药O2O，取决于药师配置、审方系统、处方留痕和用药咨询。平台若不能核验审方质量，就很难把处方药场景规模化。\n\n### 3. 慢病和DTP场景需要更长链路\n\n慢病药和DTP药不只是一次配送，它们涉及复诊、处方续配、医保支付、患者教育和用药随访。处方药监管政策意味着平台要从“交易撮合”升级为“处方与服务链路组织者”。\n''',
'07-政策与监管库/平台监管/平台监管政策汇总.md': '''## 四、政策逻辑与业务应用分析\n\n### 1. 平台责任从“提供入口”扩展到“管理交易”\n\n医药平台不能只说自己是流量入口。入驻审核、药品信息展示、处方提示、交易留痕、投诉处理和风险处置都会影响平台责任。平台越深入买药交易，越需要证明自己不是简单导流。\n\n### 2. 价格补贴和流量分配会影响药店经营质量\n\n平台补贴可能带来订单增长，也可能压缩药店毛利、诱发低价竞争和不规范促销。对即时零售医药来说，补贴不能只看用户增长，还要看是否影响药品质量、药师服务和合规销售。\n\n### 3. 平台监管会推动药店和药企提高资料颗粒度\n\n平台为了管理入驻和交易风险，会要求药店提供资质、库存、医保、审方、配送和售后数据；药企也需要提供合规药品信息、广告审查和追溯资料。监管越细，平台越需要数据化治理能力。\n''',
'07-政策与监管库/药品流通/药品流通政策汇总.md': '''## 四、政策逻辑与业务应用分析\n\n### 1. 药品流通政策决定“送药”不能等同于“送普通商品”\n\n药品流通涉及采购、储存、销售、追溯、配送、召回和不良反应。即时零售把履约速度提高了，但没有降低质量管理要求。相反，配送半径、交接方式和售后处理变得更复杂。\n\n### 2. 追溯能力会成为平台和药店合作的重要门槛\n\n一物一码和追溯体系可以帮助识别药品来源、批次和去向。平台买药如果无法把订单、药店、药品批次和用户签收关联起来，就很难支持召回、投诉和基金监管。\n\n### 3. 药企进入O2O渠道要关注终端履约质量\n\n药企不能只看平台曝光和搜索转化，还要看药店是否能正确储存、销售、追溯和处理售后。对品牌OTC来说，这影响用户体验；对处方药、冷链药和特药来说，这影响安全和合规。\n''',
'07-政策与监管库/补充资料/广东医保药店与线上医保政策样本.md': '''## 四、广东本地政策带来的业务分析\n\n### 1. 广东多入口模式会改变平台角色\n\n广东样本显示，用户可以通过“粤医保”、微信/支付宝小程序和药店合作线上渠道进入买药刷医保路径。这意味着平台不是唯一入口，而是广东线上医保购药生态中的一个承接渠道。平台要证明的不是“有没有入口”，而是能否与广东本地医保入口、定点药店和电子凭证支付形成稳定衔接。\n\n### 2. 广东定点药店需要同时面对线上展示和医保风控\n\n广东本地药店如果参与线上医保购药，不仅要展示商品和承接订单，还要处理医保电子凭证、处方、审方、支付和配送。对药店来说，线上医保不是增加一个销售渠道，而是增加一套可审计的交易和服务链路。\n\n### 3. 广东用户路径更灵活，但可用性更依赖本地系统\n\n多入口提高了用户触达，但用户实际能否完成医保购药，取决于所在城市、药店是否接入、药品是否可支付、处方是否可承接。广东样本的业务价值在于展示了“省级入口 + 平台入口 + 药店渠道”的协同可能。\n''',
'07-政策与监管库/补充资料/北京医保药店与线上医保政策样本.md': '''## 四、北京本地政策带来的业务分析\n\n### 1. 北京样本更偏“互联网复诊后购药”\n\n北京政策的重点不是普通OTC平台买药，而是互联网复诊、在线处方、医保实时结算和取药/配送的衔接。这说明北京线上医保购药更依赖医疗服务链路，平台如果参与，需要证明自己连接的是合规处方和定点服务。\n\n### 2. 北京定点药店的价值在处方承接\n\n北京样本中，定点零售药店可能成为在线处方后的取药或配送节点。药店的竞争点不只是库存和距离，还包括能否承接合规处方、医保结算和配送服务。\n\n### 3. 北京用户体验取决于复诊、处方和取药链路是否顺畅\n\n用户能否在线完成服务，不只取决于平台页面，还取决于互联网复诊资格、电子实名认证、在线处方、医保结算和取药/配送选择是否打通。\n''',
'07-政策与监管库/补充资料/上海医保药店与线上医保政策样本.md': '''## 四、上海本地政策带来的业务分析\n\n### 1. 上海样本更像“药店互联网购药医保支付”模型\n\n上海公开信息强调定点零售药店互联网购药医保在线支付，并提到平台入口和药品费个人账户支付。这说明上海的重点是把线下定点药店服务迁移到线上交易场景，而不是先从互联网复诊切入。\n\n### 2. 费用拆分会影响平台页面和用户预期\n\n上海样本明确区分药品费、跑腿费和包装费。平台如果承接上海医保购药，需要在页面上清楚展示哪些费用可以医保个人账户支付，哪些费用必须现金支付，否则容易造成用户误解。\n\n### 3. 上海药店接入质量决定医保购药体验\n\n平台只是入口，用户体验取决于接入的定点药店是否有货、能否完成医保结算、能否及时履约。上海样本对平台的启发是：医保支付能力最终要落到药店级服务。\n''',
'07-政策与监管库/补充资料/浙江医保药店与线上医保政策样本.md': '''## 四、浙江本地政策带来的业务分析\n\n### 1. 浙江样本更像平台和药店的准入规则\n\n“浙里云药房”把第三方平台、定点药店、系统接口、实名认证、风控和医保结算放在同一套实施指南中。它的业务意义不是展示一个活动入口，而是明确谁能接入、如何接入、接入后承担什么责任。\n\n### 2. 浙江平台竞争会转向系统能力竞争\n\n第三方平台若要参与浙江线上医保购药，需要满足备案、实名、风控、结算和数据能力。这会让平台竞争从流量和履约，进一步转向医保系统对接和合规治理能力。\n\n### 3. 浙江药店可以自建或入驻，但责任不会消失\n\n浙江样本允许定点药店自建云药房或入驻第三方平台，但医保结算、订单履约、数据留痕和服务质量仍需要药店承担。对药店来说，选择平台只是渠道方式，不是责任转移。\n'''
}
for p,b in blocks.items():
    insert_before_sources(p,b)
